// hasFeature reports whether |f| appears in |md|'s advertised
// features list. FEATURE_UNSPECIFIED is treated as always absent.
// |md| may be nil.
func hasFeature(md *remotesapi.GetRepoMetadataResponse, f remotesapi.Feature) bool {
	if md == nil || f == remotesapi.Feature_FEATURE_UNSPECIFIED {
		return false
	}
	return slices.Contains(md.Features, f)
}

func NewDoltChunkStoreFromPath(
	ctx context.Context,
	nbf *types.NomsBinFormat,
	path, host string,
	wsval bool,
	csClient remotesapi.ChunkStoreServiceClient,
	opts ...ChunkStoreOption,
) (*DoltChunkStore, error) {
	var repoId *remotesapi.RepoId

	path = strings.Trim(path, "/")
	tokens := strings.Split(path, "/")
	if len(tokens) == 2 {
		org := tokens[0]
		repoName := tokens[1]
		repoId = &remotesapi.RepoId{
			Org:      org,
			RepoName: repoName,
		}
	}

	metadata, err := csClient.GetRepoMetadata(ctx, &remotesapi.GetRepoMetadataRequest{
		RepoId:   repoId,
		RepoPath: path,
		ClientRepoFormat: &remotesapi.ClientRepoFormat{
			NbfVersion: nbf.VersionString(),
			NbsVersion: nbs.StorageVersion,
		},
	})
	if err != nil {
		return nil, err
	}

	repoToken := new(atomic.Value)
	if metadata.RepoToken != "" {
		repoToken.Store(metadata.RepoToken)
	}

	cs := &DoltChunkStore{
		repoId:      repoId,
		repoPath:    path,
		repoToken:   repoToken,
		host:        host,
		csClient:    csClient,
		finalizer:   func() error { return nil },
		cache:       newMapChunkCache(),
		wb:          newMapWriteBuffer(),
		metadata:    metadata,
		nbf:         nbf,
		httpFetcher: globalHttpFetcher,
		params:      defaultRequestParams,
		wsValidate:  wsval,
	}
	err = cs.loadRoot(ctx)
	if err != nil {
		return nil, err
	}
	return cs, nil
}

