var ErrRemoteTableFileGet = errors.New("HTTP GET for remote table file failed")

func sanitizeSignedUrl(url string) string {
	si := strings.Index(url, "Signature=")
	if si == -1 {
		return url
	}
	ei := strings.Index(url[si:], "&")
	if ei == -1 {
		return url[:si+15] + "..."
	} else {
		return url[:si+15] + "..." + url[si:][ei:]
	}
}

// Open returns an io.ReadCloser which can be used to read the bytes of a table file.
func (drtf DoltRemoteTableFile) Open(ctx context.Context) (io.ReadCloser, uint64, error) {
	if drtf.info.RefreshRequest != nil && drtf.info.RefreshAfter != nil && time.Now().After(drtf.info.RefreshAfter.AsTime()) {
		// The request was prebuilt by the server (echo pattern);
		// the client is authoritative for its own capability set
		// and must stamp it at send time. See the ClientCapability
		// enum comment in chunkstore.proto.
		drtf.info.RefreshRequest.ClientCapabilities = clientCapabilities
		resp, err := drtf.dcs.csClient.RefreshTableFileUrl(ctx, drtf.info.RefreshRequest)
		if err == nil {
			drtf.info.Url = resp.Url
			drtf.info.RefreshAfter = resp.RefreshAfter
		}
	}

	req, err := http.NewRequestWithContext(ctx, http.MethodGet, drtf.info.Url, nil)
	if err != nil {
		return nil, 0, err
	}

	resp, err := drtf.dcs.httpFetcher.Do(req)
	if err != nil {
		return nil, 0, err
	}

	if resp.StatusCode/100 != 2 {
		// XXX: If we fail to fetch, and we have the ability
		// to refresh the URL, set ourselves up to refresh the
		// next time we are used. This can help if the
		// remoteapi endpoint gave us a URL that actually
		// expires for some reason before the RefreshAfter
		// timestamp. (Local clock drift, remote key rotation,
		// etc.)
		if drtf.info.RefreshAfter != nil {
			drtf.info.RefreshAfter = timestamppb.Now()
			drtf.info.RefreshAfter.Seconds -= 10
		}
		defer resp.Body.Close()
		body := make([]byte, 4096)
		n, _ := io.ReadFull(resp.Body, body)
		return nil, 0, fmt.Errorf("%w: status code: %d;\nurl: %s\n\nbody:\n\n%s\n", ErrRemoteTableFileGet, resp.StatusCode, sanitizeSignedUrl(drtf.info.Url), string(body[0:n]))
	}

	return resp.Body, uint64(resp.ContentLength), nil
}

